INSERT INTO `landscape_video` (`id`, `category`, `location`, `author_id`, `data`) VALUES ('vid-22', '山岳风光', '瑞士·马特洪峰', 'ph-7', '{"id":"vid-22","url":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","poster":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","title":"瑞士阿尔卑斯雪山","category":"山岳风光","location":"瑞士·马特洪峰","authorId":"ph-7","author":"刘洋","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","duration":"8:35","views":28500,"likes":4200,"loves":2200,"bookmarks":1500,"shares":820,"comments":420,"resolution":"4K","fps":24,"date":"2024-01-18","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"mountain"},{"dimension":"location","category":"europe","subCategory":"western-europe"},{"dimension":"time","category":"daytime","subCategory":"golden-hour"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"perspective","subCategory":"panorama"},{"dimension":"style","category":"mood","subCategory":"powerful"},{"dimension":"element","category":"natural-element","subCategory":"ice"}]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-1', '西藏星空摄影完全指南', '摄影技巧', '西藏阿里', 'ph-7', 'intermediate', '{"id":"guide-1","title":"西藏星空摄影完全指南","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/1.webp","excerpt":"从器材准备到拍摄参数设置，带你记录藏区最震撼的星空与银河","authorId":"ph-7","author":"刘洋","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","authorVerified":true,"category":"摄影技巧","location":"西藏阿里","locationId":"china","tags":["星空","西藏","摄影"],"views":3200,"likes":156,"loves":234,"bookmarks":89,"shares":67,"difficulty":"intermediate","duration":"1-3天","season":"春季","budget":"中高","rating":4.8,"publishDate":"2024-01-15","highlights":["银河拱桥拍摄","星轨叠加技巧","高原防寒保暖"],"travelMode":"摄影团","sceneryTheme":"星空","type":"deep-tour","typeName":"深度游","date":"2024-01-15","readTime":"15","categoryTags":[{"dimension":"theme","category":"sky","subCategory":"starry"},{"dimension":"location","category":"china","subCategory":"china-west"},{"dimension":"time","category":"nighttime","subCategory":"night-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"special-tech","subCategory":"star-trail"},{"dimension":"style","category":"mood","subCategory":"powerful"},{"dimension":"element","category":"natural-element","subCategory":"reflection"}],"sections":[{"title":"最佳拍摄地点","items":["阿里地区 - 冈仁波齐神山脚下，海拔4700米，无光污染，银河清晰可见","纳木错湖畔 - 海拔4718米，湖面倒影星空，可拍摄银河拱桥","珠峰大本营 - 世界之巅观星，南半球星空独特视角","羊卓雍措 - 距拉萨较近，交通便利，适合初级星空摄影"]},{"title":"拍摄参数设置","items":["广角镜头：16-35mm f/2.8，ISO 3200-6400，曝光20-30秒","星轨拍摄：ISO 800，单张曝光120秒，连续拍摄200张叠加","银河拱桥：竖拍多张，后期使用PTGui拼接全景","人物星景：ISO 1600，曝光15秒，人物补光用头灯"]},{"title":"行程安排建议","items":["第1天：拉萨适应高原环境，检查器材装备","第2-3天：纳木错拍摄，住宿湖边帐篷营地","第4-6天：阿里地区，冈仁波齐转山拍摄","第7-8天：返回拉萨，整理素材，后期处理"]},{"title":"高原注意事项","items":["提前一周服用红景天，预防高原反应","夜间拍摄注意保暖，羽绒服、暖宝宝必备","高原紫外线强，白天需戴墨镜、涂抹防晒霜","器材电池低温耗电快，携带备用电池贴身保暖"]}],"equipments":[{"title":"相机机身","icon":"📷","items":["全画幅相机：索尼A7S3或尼康Z6II，高感性能优秀","备用机身：防止高原故障导致无法拍摄","电池：至少4块，贴身存放防止低温掉电"]},{"title":"镜头选择","icon":"🔍","items":["超广角：14mm f/1.8 或 20mm f/1.4，拍摄银河全景","广角变焦：16-35mm f/2.8，通用性强","长焦：70-200mm f/2.8，拍摄星云特写"]},{"title":"三脚架配件","icon":"🦿","items":["专业三脚架：碳纤维材质，稳定且轻便","星野赤道仪：跟踪星空，实现更长曝光","快门线：避免按快门震动，间隔拍摄必备"]}],"tips":[{"title":"天气选择","content":"选择无云无月的晴朗夜晚，月相最好在新月前后一周。提前查询卫星云图，避开阴雨天气。","type":"info"},{"title":"对焦技巧","content":"手动对焦模式，将对焦环转至无穷远后再往回转一点点，拍摄测试放大查看星星是否清晰。","type":"tip"},{"title":"高原反应警告","content":"阿里地区海拔超过4500米，切勿剧烈运动。如出现头痛、呼吸困难等症状，立即下撤至低海拔地区。","type":"warning"}],"bestTime":"每年10月至次年4月，旱季天气晴朗，夜间时间长，是最佳拍摄季节。其中11-12月银河最清晰。","weather":"高原天气多变，白天可能晴朗，夜间突然降温。昼夜温差可达20°C，需准备四季衣物。夜间温度常在-10°C至-30°C。","transportation":"建议从拉萨包车或自驾前往，沿途加油站较少，需提前加满油。阿里地区路况较差，建议越野车。","accommodation":"纳木错、羊卓雍措有湖边帐篷营地，条件简陋但观星方便。阿里地区住宿选择有限，建议自带睡袋。","budgetDetail":"人均约8000-15000元，包含：包车3000-5000元，住宿1000-2000元，门票500元，装备折旧2000元，餐饮1000元。","safetyNotes":["高原反应：提前服用红景天，准备氧气瓶，症状严重立即下撤","低温防护：夜间拍摄需羽绒服、暖宝宝、手套，防止冻伤","交通安全：阿里路段野生动物多，夜间行车注意避让","器材保护：三脚架低温变脆，避免用力过猛，电池贴身保暖"],"routePoints":["拉萨(3650m) - 适应1天","羊卓雍措(4441m) - 初次高原拍摄","纳木错(4718m) - 湖畔银河倒影","珠峰大本营(5200m) - 世界之巅星空","阿里冈仁波齐(4700m) - 深度星空摄影"],"recommendedGear":["羽绒服、冲锋衣、保暖内衣","暖宝宝、发热鞋垫、暖手宝","墨镜、防晒霜SPF50+、唇膏","头灯（红光模式）、保温杯","氧气瓶、常用药、红景天"],"postProcessing":["使用Lightroom进行基础调色，提高曝光、降低高光","使用Starry Landscape Stacker叠加降噪，提升画质","银河拱桥使用PTGui拼接，注意重叠区域约30%","星轨使用StarStaX叠加，可选择间隙模式和渐隐模式"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-2', '冰岛极光摄影终极攻略', '地点攻略', '冰岛', 'ph-1', 'advanced', '{"id":"guide-2","title":"冰岛极光摄影终极攻略","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/2.webp","excerpt":"从选址到参数设置全方位解析，涵盖冰岛环岛最佳极光观测点","authorId":"ph-1","author":"张伟","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/1.webp","authorVerified":true,"category":"地点攻略","location":"冰岛","locationId":"europe","tags":["极光","冰岛","自驾"],"views":5600,"likes":289,"loves":456,"bookmarks":156,"shares":89,"difficulty":"advanced","duration":"4-7天","season":"夏季","budget":"高","rating":4.9,"publishDate":"2023-12-10","highlights":["草帽山极光","冰河湖倒影","蓝冰洞探险"],"travelMode":"自驾游","sceneryTheme":"极光","type":"photo-tour","typeName":"摄影团","date":"2023-12-10","readTime":"20","categoryTags":[{"dimension":"theme","category":"sky","subCategory":"aurora"},{"dimension":"location","category":"europe","subCategory":"northern-europe"},{"dimension":"time","category":"nighttime","subCategory":"night-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"exposure","subCategory":"long-exposure"},{"dimension":"style","category":"mood","subCategory":"mysterious"},{"dimension":"element","category":"natural-element","subCategory":"ice"}],"sections":[{"title":"极光观测地点","items":["辛格维利尔国家公园 - 世界遗产地，极光下的裂谷绝美","杰古沙龙冰河湖 - 冰川湖泊倒影极光，梦幻场景","草帽山(Kirkjufell) - 冰岛最具标志性的极光拍摄点","黑沙滩 - 极光映照黑色沙滩，神秘氛围"]},{"title":"极光拍摄参数","items":["基础设置：ISO 1600-3200，光圈f/2.8，曝光10-20秒","强极光：ISO 800，曝光15秒，避免过曝","弱极光：ISO 3200，曝光25秒，提升亮度","延时摄影：间隔3-5秒拍摄，后期合成视频"]},{"title":"自驾路线规划","items":["黄金圈：雷克雅未克-辛格维利尔-盖歇尔-黄金瀑布，2-3天","南岸线：塞里雅兰瀑布-黑沙滩-杰古沙龙，3-4天","斯奈山半岛：草帽山-阿尔纳斯塔皮，2天","冰岛环岛：全程约1332公里，建议10-14天"]},{"title":"蓝冰洞探险","items":["必须跟随专业向导，不可独自进入","冬季(11-3月)冰洞稳定，夏季危险禁止进入","冰洞内拍摄需三脚架，曝光2-5秒","佩戴冰爪，头盔，安全装备不可省"]}],"equipments":[{"title":"相机配置","icon":"📷","items":["全画幅机身：索尼A7III/A7RIV，尼康Z7II","广角镜头：14mm f/1.8 或 24mm f/1.4，大光圈必备","备用电池：低温环境下电池耗电快，至少3块"]},{"title":"防寒装备","icon":"🧥","items":["专业羽绒服：Canada Goose或北面Summit系列","保暖内衣：美利奴羊毛打底，抓绒中间层","防风手套：触屏手套方便操作相机"]},{"title":"自驾装备","icon":"🚗","items":["四驱车辆：冬季必须四驱，建议租赁SUV","防滑链：北部和东部可能需要，租赁时确认","应急包：拖车绳、铲子、手电筒、急救包"]}],"tips":[{"title":"极光预测","content":"使用Aurora Forecast或冰岛气象局网站查看KP指数，KP≥3即可看到极光。同时关注云层覆盖情况。","type":"info"},{"title":"对焦设置","content":"极光距离很远，手动对焦设置在无穷远。可以在白天预对焦并标记位置，夜间直接使用。","type":"tip"},{"title":"天气警告","content":"冰岛天气变化剧烈，暴风雪可能导致道路封闭。出发前查看road.is路况信息，遇红色警报切勿上路。","type":"warning"}],"bestTime":"每年9月至次年4月，极光季节。其中10-2月极光最活跃，12-1月夜晚最长。","weather":"冰岛气候多变，一天可经历四季。冬季温度-5°C至5°C，但体感温度因风寒效应更低。风速可达30m/s。","transportation":"建议租车自驾，Blue Car Rental或Hertz都可靠。冬季必须四驱，购买全险，砂石损伤保险很重要。","accommodation":"首都酒店选择多，乡村地区Guesthouse为主。建议提前预订，极光季节热门日期很快满房。","budgetDetail":"人均约20000-35000元，包含：机票5000-8000元，租车7000-12000元，住宿5000-8000元，餐饮3000元，门票活动2000元。","safetyNotes":["暴风雪警告：红色警报时切勿上路，留在原地等待","海边安全：北大西洋风浪巨大，远离海岸线，谨防突发大浪","冰川危险：不可踏上冰川，必须在向导带领下进入","极寒防护：防止冻伤，暴露皮肤不超过10分钟"],"routePoints":["雷克雅未克 - 适应气候，采购物资","黄金圈(2天) - 辛格维利尔极光拍摄","南岸线(3天) - 冰河湖极光倒影","斯奈山(2天) - 草帽山经典机位","北部环线(可选) - 钻石沙滩，海鹦"],"recommendedGear":["专业羽绒服、羊毛内衣、抓绒衣","触屏手套、羊毛帽、围巾","冰爪、防滑鞋、防水裤","暖宝宝、保温杯、头灯","应急食品、充电宝、GPS"],"postProcessing":["Lightroom：提高曝光，降低高光，增强绿色极光","Luminar AI：使用AI增强极光结构和色彩","Photoshop：叠加多张提升信噪比，增强细节","Premiere：制作延时视频，添加背景音乐"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-3', '巴塔哥尼亚风光摄影深度游', '地点攻略', '巴塔哥尼亚', 'ph-2', 'advanced', '{"id":"guide-3","title":"巴塔哥尼亚风光摄影深度游","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/3.webp","excerpt":"探索世界尽头，拍摄百内三塔、菲茨罗伊峰等南美极致风光","authorId":"ph-2","author":"李明","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/2.webp","authorVerified":true,"category":"地点攻略","location":"巴塔哥尼亚","locationId":"south-america","tags":["风光","山岳","徒步"],"views":4800,"likes":312,"loves":523,"bookmarks":234,"shares":145,"difficulty":"advanced","duration":"8-14天","season":"秋季","budget":"高","rating":4.7,"publishDate":"2024-02-28","highlights":["百内三塔日出","菲茨罗伊倒影","冰川徒步"],"travelMode":"徒步游","sceneryTheme":"山岳","type":"hiking","typeName":"徒步","date":"2024-02-28","readTime":"18","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"mountain"},{"dimension":"location","category":"america","subCategory":"south-america"},{"dimension":"time","category":"daytime","subCategory":"golden-hour"},{"dimension":"weather","category":"cloudy-weather","subCategory":"partly-cloudy"},{"dimension":"technique","category":"perspective","subCategory":"panorama"},{"dimension":"style","category":"mood","subCategory":"powerful"},{"dimension":"element","category":"natural-element","subCategory":"rocks"}],"sections":[{"title":"核心拍摄点","items":["百内三塔 - 世界最美山峰之一，日出时分金色光芒","格雷冰川 - 南极外最大冰川，可乘船近距离拍摄","菲茨罗伊峰 - 登山者圣地，湖面倒影绝美","佩里托莫雷诺冰川 - 持续崩塌的活冰川"]},{"title":"徒步路线","items":["W线路：百内国家公园经典路线，4-5天，难度中等","O线路：环线徒步，8-9天，需野外露营经验","菲茨罗伊徒步：埃尔查尔滕出发，单日往返","冰川徒步：佩里托莫雷诺冰川行走，需向导带领"]},{"title":"拍摄时间","items":["日出：百内三塔日出约6:00，需提前2小时出发","日落：菲茨罗伊峰日落约20:00，黄金时刻较长","星空：南半球星空独特，可见大小麦哲伦星云","季节：11-3月南半球夏季，气候温和适合徒步"]},{"title":"住宿选择","items":["百内：Refugio(山屋)需提前预订，热门日期很快满","埃尔查尔滕：小镇住宿选择多，徒步起点","埃尔卡拉法特：旅游小镇，佩里托莫雷诺基地","露营：O线路需携带帐篷，公园内指定营地"]}],"equipments":[{"title":"徒步装备","icon":"🥾","items":["登山鞋：防水高帮，提前磨合防止磨脚","登山杖：双杖使用，减轻膝盖压力","背包：50-60L容量，防雨罩必备"]},{"title":"摄影器材","icon":"📷","items":["广角镜头：16-35mm，拍摄山峰全景","长焦镜头：70-200mm，压缩感构图","三脚架：轻便碳纤维，徒步减重关键"]},{"title":"防风保暖","icon":"🧥","items":["冲锋衣：Gore-Tex材质，巴塔哥尼亚风力强劲","保暖层：羽绒或抓绒，夜间温度可达0°C","防风帽：防止强风，护耳款式更佳"]}],"tips":[{"title":"风力警告","content":"巴塔哥尼亚以狂风著称，风速可达100km/h。三脚架需加重物固定，冲锋衣必须防风。","type":"warning"},{"title":"预订提示","content":"百内国家公园Refugio必须提前预订，旺季(12-2月)需提前3-6个月。Fantástico Sur官网预订。","type":"info"},{"title":"摄影机位","content":"百内三塔最佳机位在Nordenskjöld湖畔，需徒步前往。菲茨罗伊最佳机位在Laguna de los Tres。","type":"tip"}],"bestTime":"11月至次年3月，南半球夏季。其中12-1月最温暖，但游客最多。10月和3月人少景美。","weather":"巴塔哥尼亚天气极其多变，一天四季。夏季温度5-15°C，风力强劲，阵雨频繁。需随时准备防雨装备。","transportation":"从布宜诺斯艾利斯飞埃尔卡拉法特，再乘大巴到埃尔查尔滕。百内从蓬塔阿雷纳斯进入。","accommodation":"Refugio提供床位和餐饮，约$50-80/晚。露营约$15/晚。小镇酒店$80-150/晚。","budgetDetail":"人均约25000-40000元，包含：机票8000-12000元，徒步许可3000元，住宿5000-8000元，餐饮3000元，装备租赁2000元。","safetyNotes":["风力危险：强风可能导致徒步危险，注意天气预警","失温防护：雨天+大风极易失温，随时保持干燥","野生动物：注意美洲狮，露营食物密封存放","通讯信号：山区无信号，携带卫星电话或GPS求救器"],"routePoints":["布宜诺斯艾利斯 - 入境中转","埃尔卡拉法特 - 佩里托莫雷诺冰川","埃尔查尔滕 - 菲茨罗伊峰徒步","蓬塔阿雷纳斯 - 百内国家公园","百内三塔 - 经典机位拍摄"],"recommendedGear":["防水登山鞋、登山杖、大背包","冲锋衣、羽绒内胆、防风帽","防晒霜、墨镜、唇膏","水袋、能量棒、急救包","充电宝、防水袋、头灯"],"postProcessing":["Lightroom：增强蓝调天空，提升冰川通透感","全景拼接：PTGui拼接山峰全景，注意重叠30%","HDR合成：日出日落大光比，包围曝光合成","降噪处理：高感光度拍摄，使用Topaz Denoise"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-4', '日本樱花季摄影全攻略', '地点攻略', '日本', 'ph-3', 'beginner', '{"id":"guide-4","title":"日本樱花季摄影全攻略","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/4.webp","excerpt":"从京都到东京，记录日本樱花季最美瞬间，古建筑与樱花完美结合","authorId":"ph-3","author":"王芳","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/3.webp","authorVerified":true,"category":"地点攻略","location":"日本","locationId":"asia","tags":["樱花","森林","人文"],"views":7200,"likes":456,"loves":687,"bookmarks":345,"shares":198,"difficulty":"beginner","duration":"15-30天","season":"春季","budget":"中","rating":4.6,"publishDate":"2024-03-20","highlights":["京都古寺樱花","东京夜樱","奈良鹿与花"],"travelMode":"向导游","sceneryTheme":"樱花季","type":"free-travel","typeName":"自由行","date":"2024-03-20","readTime":"12","categoryTags":[{"dimension":"theme","category":"season","subCategory":"spring"},{"dimension":"location","category":"asia","subCategory":"japan"},{"dimension":"time","category":"daytime","subCategory":"morning-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"composition","subCategory":"framing"},{"dimension":"style","category":"mood","subCategory":"romantic"},{"dimension":"element","category":"natural-element","subCategory":"flowers"}],"sections":[{"title":"最佳拍摄地点","items":["京都 - 清水寺、金阁寺、哲学之道，古寺樱花经典","东京 - 千鸟渊、上野公园、新宿御苑，都市樱花","奈良 - 奈良公园、吉野山，樱花与鹿的结合","大阪 - 大阪城公园、造币局樱花通道"]},{"title":"樱花拍摄技巧","items":["逆光拍摄：阳光穿透花瓣，呈现通透质感","古建筑框景：使用门洞、窗框构图，增加层次","低角度仰拍：蓝天背景，突出花枝形态","大光圈虚化：f/1.8-2.8虚化背景，突出主体"]},{"title":"夜樱拍摄","items":["千鸟渊夜樱：灯光映照护城河，倒影绝美","清水寺夜樱：灯光设计专业，氛围梦幻","拍摄参数：ISO 800-1600，光圈f/2.8，曝光1-2秒","三脚架必备：夜间拍摄稳定性要求高"]},{"title":"行程规划","items":["第1-3天：京都深度拍摄，清晨避开人群","第4-5天：奈良一日游，下午返回京都","第6-8天：东京都市樱花，夜樱重点","第9-10天：周边小众景点，轻井泽等"]}],"equipments":[{"title":"镜头选择","icon":"🔍","items":["大光圈定焦：50mm f/1.4 或 85mm f/1.8，虚化效果","广角镜头：16-35mm，建筑与樱花结合","长焦镜头：70-200mm，压缩感构图，远距离拍摄"]},{"title":"配件装备","icon":"📷","items":["三脚架：夜樱拍摄必备，轻便旅行款即可","偏振镜：消除叶片反光，增强色彩饱和","渐变滤镜：平衡天空与地面光比"]},{"title":"拍摄道具","icon":"🌸","items":["汉服/和服：人像拍摄增加氛围感","油纸伞、团扇：经典日式道具","手持花瓣：拍摄散落效果"]}],"tips":[{"title":"樱花前线","content":"关注日本气象厅樱花前线预报，每年3月下旬从九州开始北上。京都东京约3月底4月初盛开。","type":"info"},{"title":"避人群技巧","content":"热门景点清晨6-7点到达，避开人流高峰。工作日比周末人少，雨天樱花更美且人少。","type":"tip"},{"title":"花期短","content":"樱花花期仅7-10天，错过需等一年。建议关注实时开花情况，灵活调整行程。","type":"warning"}],"bestTime":"3月下旬至4月上旬，具体视樱花前线预报。京都、东京约3月28日-4月5日盛开。","weather":"春季日本气候温和，温度10-20°C。偶有春雨，樱花雨后更美。早晚温差大，需备外套。","transportation":"JR Pass推荐，新干线便捷。京都以公交为主，建议购买一日券。东京地铁发达，西瓜卡便捷。","accommodation":"京都建议住祇园或河原町附近，方便清晨拍摄。东京住新宿或上野，交通便利。","budgetDetail":"人均约12000-20000元，包含：机票3000-5000元，住宿4000-6000元，交通2000元，餐饮2000元，门票500元。","safetyNotes":["人流密集：热门景点注意财物安全，避免拥挤","交通规则：日本靠左行驶，注意安全","花粉过敏：春季花粉严重，过敏者准备药物","礼仪文化：寺庙内安静，不可使用自拍杆"],"routePoints":["东京入境 - 适应时差","京都(3天) - 古寺樱花深度拍摄","奈良(1天) - 樱花与鹿","东京(3天) - 都市樱花与夜樱","周边(可选) - 轻井泽、富士山"],"recommendedGear":["轻便相机包、三脚架","偏振镜、渐变滤镜","舒适步行鞋、轻便外套","充电宝、备用电池","雨具、防晒用品"],"postProcessing":["Lightroom：增强粉色调，提高明亮度","人像修饰：使用PortraitPro处理人像","虚化增强：后期可进一步增强虚化效果","色调分离：高光偏粉，暗部偏蓝，梦幻氛围"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-5', '城市夜景延时摄影技巧', '摄影技巧', '全国城市', 'ph-1', 'intermediate', '{"id":"guide-5","title":"城市夜景延时摄影技巧","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/5.webp","excerpt":"车流光轨、星空城市、繁华夜景，掌握城市延时摄影核心技术","authorId":"ph-1","author":"张伟","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/1.webp","authorVerified":true,"category":"摄影技巧","location":"全国城市","locationId":"china","tags":["夜景","都市","延时"],"views":6400,"likes":389,"loves":412,"bookmarks":267,"shares":156,"difficulty":"intermediate","duration":"30天以上","season":"全年","budget":"低","rating":4.5,"publishDate":"2024-04-05","highlights":["车流光轨拍摄","星空城市结合","日出日落延时"],"travelMode":"骑行游","sceneryTheme":"都市风光","type":"photo-tour","typeName":"摄影技巧","date":"2024-04-05","readTime":"10","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"nightview"},{"dimension":"location","category":"china","subCategory":"china-east"},{"dimension":"time","category":"nighttime","subCategory":"dusk"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"special-tech","subCategory":"timelapse"},{"dimension":"style","category":"mood","subCategory":"dramatic"},{"dimension":"element","category":"human-element","subCategory":"roads"}],"sections":[{"title":"延时摄影场景","items":["车流光轨：立交桥、高速公路，展现城市脉动","日落黄昏：蓝金时刻过渡，天空色彩渐变","星空城市：城市灯光与星空结合，星空延时","人流穿梭：繁华商圈，人流如织的动态效果"]},{"title":"拍摄参数设置","items":["车流延时：ISO 100，f/8，曝光2-4秒，间隔3秒","日落延时：光圈优先模式，自动曝光补偿","星空延时：ISO 3200，f/2.8，曝光25秒，间隔2秒","云层延时：间隔5-10秒，展现云流动感"]},{"title":"机位选择","items":["高处俯瞰：高层建筑、山顶，大场景城市全景","天桥位置：车流正上方，光轨对称构图","水边倒影：江边、湖畔，城市倒影延时","地标建筑：结合地标拍摄，增加辨识度"]}],"equipments":[{"title":"相机设置","icon":"📷","items":["全画幅相机：高感性能好，宽容度高","广角镜头：16-35mm，大场景拍摄","间隔快门线：定时拍摄必备，可编程功能"]},{"title":"稳定装备","icon":"🦿","items":["重型三脚架：抗风稳定，延时数小时不动","沙袋配重：大风天气增加稳定性","减震垫：减少车辆震动影响"]}],"tips":[{"title":"间隔设置","content":"间隔时间影响流畅度。车流建议2-3秒，云层5-10秒，日落5秒。间隔越短越流畅，但素材越多。","type":"info"},{"title":"电池续航","content":"延时拍摄耗时长，准备外接电源或大容量充电宝。关闭非必要功能省电。","type":"tip"}],"bestTime":"日落后蓝金时刻，车灯开启后效果最佳。全年均可，夏季黄昏时间较长。","weather":"晴朗无云或薄云天气。雨天车灯反光效果佳，但需保护器材。","transportation":"城市内拍摄，地铁公交便捷。高处机位需提前联系物业管理或寻找公开观景台。","accommodation":"城市内拍摄无需特别住宿安排，可选择拍摄点附近酒店。","budgetDetail":"器材投入为主，外接电源约300元，间隔快门线约500元。拍摄地点门票0-100元。","safetyNotes":["高处安全：护栏内拍摄，大风天注意器材安全","交通拍摄：天桥等安全位置，不可在路面拍摄","器材防护：防雨罩，防止露水、雨水损坏","人身安全：夜间拍摄结伴同行，注意周边环境"],"routePoints":["机位勘察：白天提前踩点，确定构图","蓝金时刻：日落后20分钟开始拍摄","夜景延时：天完全黑后继续拍摄","素材整理：及时备份，检查效果"],"recommendedGear":["重型三脚架、间隔快门线","外接电源、大容量充电宝","广角镜头、偏振镜","防雨罩、镜头布","头灯、手机支架"],"postProcessing":["LRTimelapse：专业延时去闪处理","Lightroom：批量调色，导出序列","Premiere：导入序列，调整帧率","After Effects：稳定防抖，增强效果"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-6', '新西兰南岛自驾摄影行', '地点攻略', '新西兰', 'ph-4', 'intermediate', '{"id":"guide-6","title":"新西兰南岛自驾摄影行","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/6.webp","excerpt":"米尔福德峡湾、特卡波湖、库克山，自驾环线拍摄纯净新西兰","authorId":"ph-4","author":"陈强","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/10.webp","authorVerified":true,"category":"地点攻略","location":"新西兰","locationId":"oceania","tags":["海洋","自驾","风光"],"views":5100,"likes":345,"loves":567,"bookmarks":312,"shares":178,"difficulty":"intermediate","duration":"1-3天","season":"春季","budget":"中高","rating":4.8,"publishDate":"2024-01-28","highlights":["特卡波星空","米尔福德峡湾","库克山日出"],"travelMode":"背包游","sceneryTheme":"海洋","type":"self-drive","typeName":"自驾","date":"2024-01-28","readTime":"16","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"mountain"},{"dimension":"location","category":"oceania","subCategory":"new-zealand"},{"dimension":"time","category":"daytime","subCategory":"sunrise-time"},{"dimension":"weather","category":"cloudy-weather","subCategory":"partly-cloudy"},{"dimension":"technique","category":"perspective","subCategory":"panorama"},{"dimension":"style","category":"mood","subCategory":"peaceful"},{"dimension":"element","category":"natural-element","subCategory":"reflection"}],"sections":[{"title":"南岛经典景点","items":["特卡波湖 - 世界最佳观星地，好牧羊人教堂","米尔福德峡湾 - 世界第八奇迹，乘船游览","库克山 - 新西兰最高峰，冰川徒步","瓦纳卡湖 - 孤树打卡，镜面倒影"]},{"title":"自驾路线","items":["基督城出发 - 租车点选择多，机场取还车","特卡波(3天) - 星空摄影基地","瓦纳卡(2天) - 罗伊斯峰徒步","皇后镇(3天) - 极限运动之都","米尔福德峡湾(2天) - 世界自然遗产"]},{"title":"拍摄技巧","items":["日出日落：金色光线照射雪山，三脚架必备","星空拍摄：特卡波国际暗夜保护区，ISO 3200","湖面倒影：清晨无风时拍摄，完美镜面效果","航拍：无人机拍摄壮丽风光，注意飞行限制"]}],"equipments":[{"title":"摄影器材","icon":"📷","items":["广角镜头：16-35mm f/2.8，风光必备","长焦镜头：70-200mm，压缩感构图","三脚架：日出日落星空必备"]},{"title":"自驾装备","icon":"🚗","items":["四驱SUV：南岛路况复杂，四驱更安全","全险保险：砂石路损伤险很重要","GPS导航：离线地图，部分路段无信号"]}],"tips":[{"title":"观星最佳","content":"特卡波是世界首个国际暗夜保护区，无月光晴朗夜晚可见银河。4-9月南半球冬季夜晚最长。","type":"info"},{"title":"自驾注意","content":"新西兰靠左行驶，山路弯道多需谨慎。砂石路限速80km/h，注意让行规则。","type":"warning"}],"bestTime":"11-3月南半球夏季气候温和，4-9月冬季观星最佳。全年皆可，各有特色。","weather":"新西兰天气多变，西海岸多雨，东海岸较干燥。夏季15-25°C，冬季5-15°C。","transportation":"基督城或皇后镇机场入境，租车自驾是最佳方式。南岛公共交通有限。","accommodation":"特卡波住宿紧张需提前预订，皇后镇选择多。Motel是性价比高的选择。","budgetDetail":"人均约15000-25000元，包含：机票5000-8000元，租车6000-10000元，住宿3000-5000元，餐饮2000元。","safetyNotes":["驾驶安全：靠左行驶，山路谨慎，注意让行","户外安全：天气多变，携带防雨保暖装备","海边危险：西海岸风浪大，远离危险礁石","野生动物：注意路边动物，夜间减速慢行"],"routePoints":["基督城 - 租车出发","特卡波(3天) - 星空摄影","库克山(2天) - 冰川徒步","瓦纳卡(2天) - 孤树打卡","皇后镇(3天) - 极限运动","米尔福德峡湾(2天) - 世界自然遗产"],"recommendedGear":["广角长焦镜头、三脚架","四驱SUV、GPS导航","防雨外套、保暖衣物","防晒霜、墨镜","充电宝、相机电池"],"postProcessing":["Lightroom：增强蓝调天空，提升绿色草原","全景拼接：PTGui拼接湖景全景","HDR合成：日出日落大光比场景","色调调整：增强新西兰标志性蓝绿色调"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-7', '微距花卉摄影进阶指南', '摄影技巧', '花园公园', 'ph-3', 'intermediate', '{"id":"guide-7","title":"微距花卉摄影进阶指南","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","excerpt":"露珠、花卉、昆虫，掌握微距摄影的器材选择与拍摄技巧","authorId":"ph-3","author":"王芳","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/3.webp","authorVerified":true,"category":"摄影技巧","location":"花园公园","locationId":"china","tags":["瀑布","微距","自然"],"views":3800,"likes":234,"loves":345,"bookmarks":189,"shares":98,"difficulty":"intermediate","duration":"8-14天","season":"夏季","budget":"中","rating":4.4,"publishDate":"2024-02-15","highlights":["露珠世界","花卉特写","昆虫捕拍"],"travelMode":"邮轮游","sceneryTheme":"瀑布","type":"photo-tour","typeName":"摄影技巧","date":"2024-02-15","readTime":"8","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"forest"},{"dimension":"location","category":"china","subCategory":"china-south"},{"dimension":"time","category":"daytime","subCategory":"morning-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"perspective","subCategory":"low-angle"},{"dimension":"style","category":"color-style","subCategory":"vibrant"},{"dimension":"element","category":"natural-element","subCategory":"flowers"}],"sections":[{"title":"微距拍摄对象","items":["花卉特写：花瓣纹理、花蕊细节，背景虚化","露珠世界：晨露珠光宝气，反射成像","昆虫捕拍：蝴蝶、蜻蜓、蜜蜂，定格瞬间","植物纹理：树皮、叶脉、苔藓，微观世界"]},{"title":"拍摄技巧","items":["对焦精准：景深极浅，手动对焦更准确","稳定拍摄：三脚架必备，快门线防震","光线选择：柔光最佳，避免强烈直射光","背景处理：简洁背景，虚化杂乱元素"]}],"equipments":[{"title":"微距镜头","icon":"🔍","items":["百微镜头：100mm f/2.8，工作距离适中","60微镜头：60mm f/2.8，适合花卉","广角微距：24-70mm微距功能，多功能"]},{"title":"辅助器材","icon":"📷","items":["近摄接圈：增加放大倍率","环形闪光灯：均匀补光，无阴影","反光板：补光柔化阴影"]}],"tips":[{"title":"景深控制","content":"微距景深极浅，1:1放大时景深仅几毫米。使用f/8-16增加景深，但需注意衍射影响。","type":"info"},{"title":"拍摄时间","content":"清晨最佳，露珠未干，昆虫活跃。阴天光线柔和，适合微距。","type":"tip"}],"bestTime":"春夏花卉盛开，清晨露珠最美。全年皆可，室内可拍摄花卉。","weather":"阴天或晨光最佳，避免强烈直射阳光。室内可使用柔光箱控制光线。","transportation":"公园、植物园、花店等城市内即可拍摄，交通便利。","accommodation":"无需特别住宿，城市内拍摄即可。","budgetDetail":"微距镜头投入较大，百微约3000-8000元。配件约500-1000元。","safetyNotes":["昆虫拍摄：注意蜜蜂等昆虫，避免惊扰","植物保护：不采摘野生花卉，保护生态","器材安全：户外拍摄注意防尘防水"],"routePoints":["公园花卉 - 玫瑰、牡丹、荷花","植物园 - 热带花卉、兰花","野外自然 - 野花、昆虫","室内布景 - 人工控制光线"],"recommendedGear":["微距镜头、三脚架","环形闪光灯、反光板","喷水壶、背景布","镊子、小夹子"],"postProcessing":["Lightroom：锐化细节，增强色彩","Photoshop：堆栈叠加景深","色彩调整：饱和度提升，细节增强"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-8', '挪威峡湾摄影之旅', '地点攻略', '挪威', 'ph-2', 'intermediate', '{"id":"guide-8","title":"挪威峡湾摄影之旅","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/8.webp","excerpt":"盖朗厄尔峡湾、松恩峡湾，拍摄挪威壮丽峡湾风光与渔村人文","authorId":"ph-2","author":"李明","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/2.webp","authorVerified":true,"category":"地点攻略","location":"挪威","locationId":"europe","tags":["湖泊","峡湾","风光"],"views":4200,"likes":267,"loves":398,"bookmarks":223,"shares":134,"difficulty":"intermediate","duration":"8-14天","season":"秋季","budget":"高","rating":4.7,"publishDate":"2024-03-10","highlights":["峡湾倒影","渔村人文","雪山峡湾"],"travelMode":"房车游","sceneryTheme":"湖泊","type":"cruise","typeName":"游轮","date":"2024-03-10","readTime":"14","categoryTags":[{"dimension":"theme","category":"water","subCategory":"ocean"},{"dimension":"location","category":"europe","subCategory":"northern-europe"},{"dimension":"time","category":"daytime","subCategory":"golden-hour"},{"dimension":"weather","category":"cloudy-weather","subCategory":"cloudy"},{"dimension":"technique","category":"perspective","subCategory":"panorama"},{"dimension":"style","category":"mood","subCategory":"peaceful"},{"dimension":"element","category":"natural-element","subCategory":"reflection"}],"sections":[{"title":"峡湾景点","items":["盖朗厄尔峡湾 - 联合国世界遗产，瀑布直泻入海","松恩峡湾 - 挪威最长最深峡湾","吕瑟峡湾 - 著名布道石观景点","纳柔依峡湾 - 世界遗产，狭窄壮美"]},{"title":"摄影机位","items":["布道石：604米垂直落差，峡湾全景","精灵之路：蜿蜒山路，俯瞰峡湾","弗洛姆铁路：世界最美铁路，沿途拍摄","游船甲板：水面视角，仰拍峡湾"]}],"equipments":[{"title":"摄影器材","icon":"📷","items":["广角镜头：16-35mm，峡湾大场景","长焦镜头：压缩感，远距离拍摄","三脚架：日出日落稳定拍摄"]},{"title":"交通方式","icon":"🚗","items":["租车自驾：灵活自由，停车拍摄","游船：近距离观赏峡湾","弗洛姆铁路：经典观光路线"]}],"tips":[{"title":"天气多变","content":"挪威峡湾天气多变，雨雾常见。多准备几天，增加遇到好天气的概率。","type":"warning"},{"title":"徒步准备","content":"布道石徒步单程约4小时，需要体力。提前预订住宿，旺季很快满房。","type":"info"}],"bestTime":"5-9月，夏季气候温和，日照时间长。冬季可拍摄极光峡湾，但部分道路封闭。","weather":"峡湾气候多变，常有雨雾。夏季温度10-20°C，冬季0°C以下。准备防雨装备。","transportation":"奥斯陆或卑尔根入境，租车自驾或游船观光。公共交通发达，火车巴士可到达主要景点。","accommodation":"弗洛姆、沃斯小镇住宿选择有限，需提前预订。卑尔根酒店选择多。","budgetDetail":"人均约18000-30000元，包含：机票6000-10000元，交通3000-5000元，住宿5000-8000元，餐饮3000元。","safetyNotes":["徒步安全：布道石等徒步需体力，注意安全","天气预警：峡湾天气多变，注意天气预报","海面安全：游船注意防滑，远离船边"],"routePoints":["卑尔根 - 入境港口城市","弗洛姆 - 弗洛姆铁路起点","盖朗厄尔 - 峡湾游船","布道石 - 徒步拍摄","精灵之路 - 经典机位"],"recommendedGear":["广角长焦镜头、三脚架","防雨外套、防水裤","登山鞋、登山杖","充电宝、防雨罩"],"postProcessing":["Lightroom：增强蓝调，提升峡湾层次","全景拼接：PTGui拼接峡湾全景","HDR合成：天空与峡湾光比大"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-9', '北京胡同人文摄影指南', '摄影技巧', '北京', 'ph-5', 'beginner', '{"id":"guide-9","title":"北京胡同人文摄影指南","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/4.webp","excerpt":"探索老北京胡同文化，记录传统与现代交织的城市记忆","authorId":"ph-5","author":"林静","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/11.webp","authorVerified":true,"category":"摄影技巧","location":"北京","locationId":"china","tags":["草原","胡同","城市"],"views":3500,"likes":178,"loves":289,"bookmarks":134,"shares":89,"difficulty":"beginner","duration":"15-30天","season":"冬季","budget":"低","rating":4.5,"publishDate":"2024-03-18","highlights":["胡同光影","市井生活","建筑细节"],"travelMode":"火车游","sceneryTheme":"草原","type":"photo-tour","typeName":"摄影技巧","date":"2024-03-18","readTime":"10","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"street"},{"dimension":"location","category":"china","subCategory":"china-north"},{"dimension":"time","category":"daytime","subCategory":"afternoon-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"composition","subCategory":"leading-lines"},{"dimension":"style","category":"color-style","subCategory":"warm-tone"},{"dimension":"element","category":"human-element","subCategory":"architectural-detail"}],"sections":[{"title":"胡同拍摄点","items":["南锣鼓巷 - 最热闹胡同，人流人文","五道营胡同 - 文艺气息，咖啡馆文化","国子监街 - 古建筑，传统氛围","什刹海胡同 - 水系胡同，四合院"]},{"title":"人文拍摄","items":["老人生活：晨练、下棋、聊天","市井气息：卖菜、修车、日常生活","建筑细节：门楼、影壁、雕花","光影效果：阳光穿胡同，明暗对比"]}],"equipments":[{"title":"镜头选择","icon":"🔍","items":["35mm或50mm定焦：人文街拍经典","24-70mm变焦：灵活构图","85mm长焦：远距离不打扰"]}],"tips":[{"title":"尊重拍摄","content":"街拍人文需尊重被拍摄者，微笑示意，避免强行拍摄。建立友善的互动关系。","type":"info"}],"bestTime":"清晨老人活动、下午光影效果佳。四季皆可，冬季雪景胡同别有风味。","weather":"北京四季分明，春秋最佳，冬季雪景独特。夏季炎热需防晒。","transportation":"地铁公交便捷，胡同适合步行拍摄。","accommodation":"住胡同民宿体验老北京生活，或酒店方便舒适。","budgetDetail":"城市拍摄成本低，交通餐饮约100-200元/天。","safetyNotes":["尊重他人：街拍需尊重被拍摄者","文物保护：不可触摸破坏古建筑","交通安全：胡同内注意电动车"],"routePoints":["南锣鼓巷 - 热闹胡同","五道营 - 文艺气息","国子监 - 古建筑","什刹海 - 水系胡同"],"recommendedGear":["轻便相机、定焦镜头","舒适步行鞋","防晒或防寒装备"],"postProcessing":["Lightroom：暖色调，增强人文氛围","黑白处理：适合街拍人文"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-10', '城市夜景长曝光技巧', '摄影技巧', '上海', 'ph-6', 'intermediate', '{"id":"guide-10","title":"城市夜景长曝光技巧","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/5.webp","excerpt":"掌握城市夜景长曝光摄影，捕捉流光溢彩的都市夜晚","authorId":"ph-6","author":"赵伟","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/12.webp","authorVerified":true,"category":"摄影技巧","location":"上海","locationId":"china","tags":["冰川","长曝光","城市"],"views":2800,"likes":145,"loves":234,"bookmarks":98,"shares":67,"difficulty":"intermediate","duration":"30天以上","season":"全年","budget":"低","rating":4.3,"publishDate":"2024-02-20","highlights":["三脚架使用","ND滤镜选择","车流拍摄"],"travelMode":"摄影团","sceneryTheme":"冰川","type":"photo-tour","typeName":"摄影技巧","date":"2024-02-20","readTime":"8","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"nightview"},{"dimension":"location","category":"china","subCategory":"china-east"},{"dimension":"time","category":"nighttime","subCategory":"dusk"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"exposure","subCategory":"long-exposure"},{"dimension":"style","category":"mood","subCategory":"dramatic"},{"dimension":"element","category":"special-element","subCategory":"shadow"}],"sections":[{"title":"长曝光场景","items":["车流光轨：立交桥、高速路口","水面雾化：海边、湖边，柔化水面","云层流动：天空云层运动","城市灯光：霓虹灯、建筑灯光"]}],"equipments":[{"title":"核心器材","icon":"📷","items":["三脚架：稳定拍摄必备","ND滤镜：减光，白天长曝光","快门线：避免相机震动"]}],"tips":[{"title":"曝光计算","content":"使用ND滤镜需计算曝光时间，手机APP可辅助计算。ISO 100，小光圈f/8-16。","type":"info"}],"bestTime":"蓝金时刻、夜间。白天使用ND滤镜可拍摄长曝光。","weather":"无风或微风天气，水面平静效果好。阴天光线柔和。","transportation":"城市内拍摄，交通便利。","accommodation":"无需特别住宿。","budgetDetail":"ND滤镜约300-1000元，三脚架约500-2000元。","safetyNotes":["器材安全：三脚架稳固，防止倾倒","人身安全：夜间拍摄注意周边环境"],"routePoints":["机位勘察：白天踩点","蓝金时刻：日落拍摄","夜间：长曝光拍摄"],"recommendedGear":["三脚架、ND滤镜","快门线、相机"],"postProcessing":["Lightroom：调整曝光，增强色彩"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-11', '野生动物摄影入门', '摄影技巧', '云南', 'ph-9', 'intermediate', '{"id":"guide-11","title":"野生动物摄影入门","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/6.webp","excerpt":"从器材选择到拍摄技巧，开启野生动物摄影之旅","authorId":"ph-9","author":"黄磊","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","authorVerified":true,"category":"摄影技巧","location":"云南","locationId":"china","tags":["峡谷","自然","生态"],"views":3200,"likes":167,"loves":256,"bookmarks":112,"shares":78,"difficulty":"intermediate","duration":"1-3天","season":"春季","budget":"中高","rating":4.4,"publishDate":"2024-04-08","highlights":["伪装技巧","器材选择","耐心等待"],"travelMode":"自驾游","sceneryTheme":"峡谷","type":"photo-tour","typeName":"摄影技巧","date":"2024-04-08","readTime":"12","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"forest"},{"dimension":"location","category":"china","subCategory":"china-south"},{"dimension":"time","category":"daytime","subCategory":"morning-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"exposure","subCategory":"long-exposure"},{"dimension":"style","category":"color-style","subCategory":"vibrant"},{"dimension":"element","category":"human-element","subCategory":"people"}],"sections":[{"title":"拍摄对象","items":["鸟类：湿地、森林、观鸟点","哺乳动物：自然保护区、野生动物园","昆虫：微距拍摄，细节丰富","水下生物：潜水拍摄，珊瑚鱼类"]}],"equipments":[{"title":"野生动物器材","icon":"📷","items":["长焦镜头：400-600mm，远距离拍摄","高速连拍：捕捉动物动态","伪装帐篷：接近动物不惊扰"]}],"tips":[{"title":"耐心等待","content":"野生动物拍摄需要极大耐心，可能等待数小时。选择动物活动高峰时段：清晨、黄昏。","type":"info"}],"bestTime":"清晨黄昏动物活动频繁。不同动物有不同活动季节。","weather":"晴朗天气最佳，阴天光线柔和也可拍摄。","transportation":"自然保护区、国家公园需提前了解交通方式。","accommodation":"保护区附近住宿，方便清晨拍摄。","budgetDetail":"长焦镜头投入大，400mm约10000-30000元。伪装帐篷约1000元。","safetyNotes":["动物安全：保持距离，不可惊扰","自身安全：大型动物危险，专业向导带领"],"routePoints":["踩点了解动物活动规律","清晨黄昏拍摄最佳时段","耐心等待精彩瞬间"],"recommendedGear":["长焦镜头、三脚架","伪装帐篷、迷彩服","望远镜、对讲机"],"postProcessing":["Lightroom：裁剪构图，增强细节"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-12', '街头摄影技巧大全', '摄影技巧', '上海', 'ph-10', 'beginner', '{"id":"guide-12","title":"街头摄影技巧大全","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/7.webp","excerpt":"捕捉城市街头的精彩瞬间，记录真实生活故事","authorId":"ph-10","author":"杨梅","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/8.webp","authorVerified":true,"category":"摄影技巧","location":"上海","locationId":"china","tags":["极光","人文","城市"],"views":4100,"likes":212,"loves":345,"bookmarks":167,"shares":98,"difficulty":"beginner","duration":"4-7天","season":"夏季","budget":"低","rating":4.5,"publishDate":"2024-03-22","highlights":["快速对焦","抓拍技巧","构图法则"],"travelMode":"徒步游","sceneryTheme":"极光","type":"photo-tour","typeName":"摄影技巧","date":"2024-03-22","readTime":"10","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"street"},{"dimension":"location","category":"china","subCategory":"china-east"},{"dimension":"time","category":"daytime","subCategory":"afternoon-time"},{"dimension":"weather","category":"cloudy-weather","subCategory":"partly-cloudy"},{"dimension":"technique","category":"composition","subCategory":"rule-of-thirds"},{"dimension":"style","category":"color-style","subCategory":"muted"},{"dimension":"element","category":"human-element","subCategory":"people"}],"sections":[{"title":"街拍技巧","items":["快速反应：随时准备拍摄，瞬间即逝","隐蔽拍摄：不惊扰被摄者，自然真实","构图法则：三分法、引导线、框景","光影运用：阳光、阴影、反光"]}],"equipments":[{"title":"街拍器材","icon":"📷","items":["轻便相机：随身携带，快速抓拍","定焦镜头：35mm或50mm，经典街拍","无声快门：避免惊扰"]}],"tips":[{"title":"尊重拍摄","content":"街拍需尊重被摄者，建立友善互动。部分国家对街拍有法律限制，需了解当地法规。","type":"info"}],"bestTime":"清晨人流少，黄昏光影佳。雨天街景别有风味。","weather":"各种天气皆有特色，雨天倒影、雾天朦胧、晴天光影。","transportation":"城市步行拍摄，地铁公交便捷。","accommodation":"无需特别住宿。","budgetDetail":"器材投入为主，轻便相机约3000-10000元。","safetyNotes":["尊重他人：街拍需尊重被摄者","财物安全：注意相机等贵重物品"],"routePoints":["商业街：人流密集","老街区：人文氛围","市场：市井气息"],"recommendedGear":["轻便相机、定焦镜头","舒适步行鞋"],"postProcessing":["Lightroom：调色，增强氛围","黑白：经典街拍风格"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-13', '西藏风光摄影深度指南', '地点攻略', '西藏', 'ph-11', 'advanced', '{"id":"guide-13","title":"西藏风光摄影深度指南","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/8.webp","excerpt":"探索西藏最美拍摄点，记录高原壮丽风光","authorId":"ph-11","author":"钱峰","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/9.webp","authorVerified":true,"category":"地点攻略","location":"西藏","locationId":"china","tags":["星空","西藏","风光"],"views":4500,"likes":234,"loves":378,"bookmarks":189,"shares":112,"difficulty":"advanced","duration":"8-14天","season":"秋季","budget":"中高","rating":4.8,"publishDate":"2024-04-02","highlights":["珠峰日出","纳木错星空","羊卓雍措"],"travelMode":"向导游","sceneryTheme":"星空","type":"deep-tour","typeName":"深度游","date":"2024-04-02","readTime":"16","categoryTags":[{"dimension":"theme","category":"nature","subCategory":"mountain"},{"dimension":"location","category":"china","subCategory":"china-west"},{"dimension":"time","category":"daytime","subCategory":"sunrise-time"},{"dimension":"weather","category":"clear-sky","subCategory":"sunny"},{"dimension":"technique","category":"perspective","subCategory":"panorama"},{"dimension":"style","category":"mood","subCategory":"powerful"},{"dimension":"element","category":"natural-element","subCategory":"rocks"}],"sections":[{"title":"西藏拍摄点","items":["珠峰大本营：世界之巅，日出日落","纳木错：圣湖倒影，星空拍摄","羊卓雍措：碧蓝湖水，雪山映衬","冈仁波齐：神山朝圣，转山拍摄"]}],"equipments":[{"title":"高原器材","icon":"📷","items":["广角长焦：风光拍摄必备","三脚架：日出日落星空","备用电池：低温耗电快"]}],"tips":[{"title":"高原反应","content":"西藏海拔高，需提前服用红景天预防。症状严重立即下撤，切勿勉强。","type":"warning"}],"bestTime":"5-10月，气候温和。冬季可拍摄雪景，但部分道路封闭。","weather":"高原气候多变，昼夜温差大。白天15°C，夜间可降至-10°C。","transportation":"拉萨入境，包车或自驾前往各景点。路况复杂，建议越野车。","accommodation":"拉萨酒店选择多，景区住宿条件有限。","budgetDetail":"人均约10000-20000元，包含：交通3000-5000元，住宿2000-4000元，门票1000元。","safetyNotes":["高原反应：提前预防，症状严重下撤","低温防护：夜间拍摄注意保暖","交通安全：高原路况复杂，谨慎驾驶"],"routePoints":["拉萨 - 适应海拔","纳木错 - 圣湖拍摄","羊卓雍措 - 碧蓝湖水","珠峰大本营 - 世界之巅"],"recommendedGear":["广角长焦镜头、三脚架","羽绒服、冲锋衣","防晒霜、墨镜","氧气瓶、常用药"],"postProcessing":["Lightroom：增强蓝调天空","全景拼接：PTGui"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-14', '人像摄影布光技巧', '摄影技巧', '北京', 'ph-12', 'intermediate', '{"id":"guide-14","title":"人像摄影布光技巧","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/1.webp","excerpt":"掌握人像摄影布光原理，打造专业质感人像作品","authorId":"ph-12","author":"孙悦","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/10.webp","authorVerified":true,"category":"摄影技巧","location":"北京","locationId":"china","tags":["山岳","布光","摄影"],"views":3800,"likes":189,"loves":298,"bookmarks":145,"shares":87,"difficulty":"intermediate","duration":"15-30天","season":"冬季","budget":"中","rating":4.4,"publishDate":"2024-03-28","highlights":["自然光运用","人工光布光","光影控制"],"travelMode":"骑行游","sceneryTheme":"山岳","type":"photo-tour","typeName":"摄影技巧","date":"2024-03-28","readTime":"11","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"architecture"},{"dimension":"location","category":"china","subCategory":"china-north"},{"dimension":"time","category":"daytime","subCategory":"golden-hour"},{"dimension":"weather","category":"cloudy-weather","subCategory":"cloudy"},{"dimension":"technique","category":"exposure","subCategory":"multiple-exposure"},{"dimension":"style","category":"mood","subCategory":"dramatic"},{"dimension":"element","category":"special-element","subCategory":"shadow"}],"sections":[{"title":"布光方式","items":["自然光：窗户光、户外散射光","单灯布光：主光+反光板补光","双灯布光：主光+辅光，立体感","多灯布光：主光、辅光、背景光、发丝光"]}],"equipments":[{"title":"布光器材","icon":"💡","items":["闪光灯：外拍灯、影室灯","柔光箱：柔化光线","反光板：补光、柔光"]}],"tips":[{"title":"光比控制","content":"人像光比一般控制在2:1至4:1，高光比更有立体感，低光比更柔和。","type":"info"}],"bestTime":"室内布光全年皆可，户外自然光早晚最佳。","weather":"阴天自然光柔和，适合人像。","transportation":"室内影棚拍摄，无需交通。","accommodation":"无需住宿。","budgetDetail":"闪光灯约1000-5000元，柔光箱约500-2000元。","safetyNotes":["电器安全：注意灯光设备用电安全"],"routePoints":["自然光拍摄","单灯练习","多灯组合"],"recommendedGear":["闪光灯、柔光箱","反光板、灯架"],"postProcessing":["Lightroom：肤色调整，光影修饰","Photoshop：精细修饰，磨皮液化"]}');
INSERT INTO `landscape_guide` (`id`, `title`, `category`, `location`, `author_id`, `difficulty`, `data`) VALUES ('guide-15', '成都街头人文之旅', '地点攻略', '成都', 'ph-8', 'beginner', '{"id":"guide-15","title":"成都街头人文之旅","cover":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/2.webp","excerpt":"漫步成都街巷，记录市井生活与美食文化","authorId":"ph-8","author":"周敏","authorAvatar":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/8.webp","authorVerified":true,"category":"地点攻略","location":"成都","locationId":"china","tags":["森林","街拍","美食"],"views":3600,"likes":178,"loves":267,"bookmarks":123,"shares":89,"difficulty":"beginner","duration":"30天以上","season":"全年","budget":"中","rating":4.5,"publishDate":"2024-03-15","highlights":["宽窄巷子","锦里古街","茶馆文化"],"travelMode":"背包游","sceneryTheme":"森林","type":"free-travel","typeName":"自由行","date":"2024-03-15","readTime":"10","categoryTags":[{"dimension":"theme","category":"urban","subCategory":"street"},{"dimension":"location","category":"china","subCategory":"china-central"},{"dimension":"time","category":"daytime","subCategory":"afternoon-time"},{"dimension":"weather","category":"cloudy-weather","subCategory":"overcast"},{"dimension":"technique","category":"composition","subCategory":"leading-lines"},{"dimension":"style","category":"color-style","subCategory":"warm-tone"},{"dimension":"element","category":"human-element","subCategory":"people"}],"sections":[{"title":"成都拍摄点","items":["宽窄巷子：老成都氛围，人流人文","锦里古街：传统建筑，小吃文化","人民公园：茶馆文化，市井生活","春熙路：都市繁华，时尚街拍"]}],"equipments":[{"title":"街拍器材","icon":"📷","items":["轻便相机：随身携带","定焦镜头：35mm或50mm","大光圈：虚化背景"]}],"tips":[{"title":"茶馆文化","content":"成都茶馆文化独特，可拍摄喝茶聊天场景。与茶客建立友善互动，获取更自然的照片。","type":"info"}],"bestTime":"清晨茶馆、下午街巷。全年皆宜，冬季火锅文化独特。","weather":"成都多阴天，光线柔和适合街拍。夏季炎热，春秋舒适。","transportation":"地铁公交发达，共享单车便捷。步行拍摄更有趣。","accommodation":"住宽窄巷子或春熙路附近，方便拍摄。","budgetDetail":"城市拍摄成本低，住宿200-500元/晚，餐饮50-100元/天。","safetyNotes":["尊重他人：街拍需尊重被摄者","财物安全：注意相机等贵重物品"],"routePoints":["宽窄巷子 - 老成都氛围","锦里古街 - 传统建筑","人民公园 - 茶馆文化","春熙路 - 都市繁华"],"recommendedGear":["轻便相机、定焦镜头","舒适步行鞋"],"postProcessing":["Lightroom：暖色调，增强人文氛围","黑白：适合街拍人文"]}');
